'use strict';
function ensureConnections(){prefs();if(!Array.isArray(state.sessionReviews))state.sessionReviews=[];if(!state.memoryUsage||typeof state.memoryUsage!=='object'||Array.isArray(state.memoryUsage))state.memoryUsage={};}
ensureConnections();
let sessionWrap=null,sessionWrapStep=0,wrapIntent='finish';
const turnNumber=()=>chatMessages.filter(m=>m.role==='assistant').length;
function explicitMemoryQuery(text){return /\b(journal|diary|quiz|weekly|remember|reflections?|patterns?|wrote|previous|last time)\b/i.test(text);}
function memoryRecentlyUsed(id){const u=state.memoryUsage[id];if(!u)return false;if(u.logId===activeLogId)return turnNumber()-u.turn<4;return Date.now()-new Date(u.at).getTime()<86400000;}
function relevantJournal(query,explicit){const words=tokenWords(query).filter(w=>w.length>2&&!memoryStop.has(w));return state.entries.filter(e=>e.memory!==false&&typeof e.text==='string').map((e,index)=>{const hay=(e.title+' '+e.text).toLowerCase();return {e,score:words.filter(w=>hay.includes(w)).length,index};}).filter(x=>(x.score>0||explicit)&&(!memoryRecentlyUsed('journal:'+x.e.id)||explicit)).sort((a,b)=>b.score-a.score||b.index-a.index).slice(0,2).map(({e})=>{const match=words.find(w=>e.text.toLowerCase().includes(w)),pos=match?e.text.toLowerCase().indexOf(match):0,start=Math.max(0,pos-400);return {id:'journal:'+e.id,title:String(e.title||'Journal').slice(0,160),date:String(e.date||'').slice(0,50),text:e.text.slice(start,start+2100)};});}
window.auraChatContext=query=>{ensureConnections();const p=prefs(),explicit=explicitMemoryQuery(query),topic=chatMessages.filter(m=>m.role==='user').slice(-2).map(m=>m.text).join(' ').slice(-1800)+' '+query,context={};if(p.journalMemory)context.journal=relevantJournal(topic,explicit);if(p.reflectionMemory){const weekly=ensureWeekly().slice().sort((a,b)=>b.week.localeCompare(a.week));const words=tokenWords(topic).filter(w=>!memoryStop.has(w));context.weekly=weekly.filter(r=>r.memory!==false).map(r=>({r,score:words.filter(w=>((r.note||'')+' '+WEEKLY_QUESTIONS.filter(q=>Number.isInteger(r.answers[q.id])).map(q=>q.question+' '+q.id).join(' ')).toLowerCase().includes(w)).length})).filter(x=>(x.score>0||explicit||(context.journal?.length&&x.r===weekly[0]))&&(!memoryRecentlyUsed('weekly:'+x.r.week)||explicit)).sort((a,b)=>b.score-a.score||b.r.week.localeCompare(a.r.week)).slice(0,3).map(({r})=>({id:'weekly:'+r.week,week:r.week,answers:Object.fromEntries(Object.entries(r.answers).filter(([key,v])=>WEEKLY_QUESTIONS.some(q=>q.id===key)&&Number.isInteger(v)&&v>=0&&v<=3)),note:String(r.note||'').slice(0,1200)}));context.sessionReviews=state.sessionReviews.filter(r=>r.memory!==false&&r.logId!==activeLogId&&(!memoryRecentlyUsed('review:'+r.id)||explicit)).slice(-2).map(r=>({id:'review:'+r.id,date:r.date,helpfulness:r.helpfulness??null,feeling:r.feeling??null,takeaway:String(r.takeaway||'').slice(0,1000)}));}if(p.country){const c=countries.find(x=>x.code===p.country);if(c)context.country=c;}if(p.journalMemory||p.reflectionMemory)context.recentMemoryIds=Object.entries(state.memoryUsage).filter(([,u])=>u.logId===activeLogId&&turnNumber()-u.turn<5).map(([id])=>id).slice(-12);return context;};
window.auraRememberUsed=ids=>{ensureConnections();for(const id of ids.filter(x=>typeof x==='string').slice(0,8))state.memoryUsage[id]={logId:activeLogId,turn:turnNumber(),at:stamp()};const keys=Object.keys(state.memoryUsage);if(keys.length>100)for(const key of keys.slice(0,keys.length-100))delete state.memoryUsage[key];};
preferencesPage=function(){const p=prefs();return `<div class="preferences narrow"><h1>Your preferences.</h1><section class="preference-section"><h2>What Aura remembers</h2><p>Selected context goes to Google with your message. You can change this anytime.</p><label class="check"><input id="journal-memory" type="checkbox" ${p.journalMemory?'checked':''}><span>Journal entries</span></label><label class="check"><input id="reflection-memory" type="checkbox" ${p.reflectionMemory?'checked':''}><span>Weekly & after-chat check-ins</span></label><details><summary>How memory works</summary><p>Aura retrieves relevant excerpts rather than training a model on your data. Entries excluded from memory stay excluded. It tracks references already mentioned to avoid repeating them, but recall and relevance can still be imperfect. Turning memory off stops future sharing, not requests already sent.</p></details></section><section class="preference-section"><h2>Country</h2><label class="sr-only" for="aura-country">Country</label><select id="aura-country"><option value="">Don’t share a country</option>${countries.map(c=>`<option value="${c.code}" ${p.country===c.code?'selected':''}>${esc(c.name)}</option>`).join('')}</select><p class="small">For local context. No GPS tracking.</p></section><section class="preference-section"><h2>A little company</h2><label for="cat-count">Cats on screen</label><select id="cat-count"><option value="1" ${p.catCount===1?'selected':''}>One</option><option value="2" ${p.catCount!==1?'selected':''}>Two</option></select></section><section class="preference-section"><h2>Private saving</h2><p class="vault-status">${esc(vaultStatus)}</p><a class="secondary" href="#logs">Open logs</a></section></div>`;};
function resetConversation(){syncAuraLog();chatVersion++;chatController?.abort();chatMessages=[];chatDraft='';chatError='';chatBusy=false;activeLogId=crypto.randomUUID();sessionWrap=null;sessionWrapStep=0;save();location.hash='chat';route();}
function openSessionWrap(intent='finish'){if(chatBusy){toast('Wait for Aura’s reply first.');return;}if(!chatMessages.some(m=>m.role==='assistant')){if(intent==='new')resetConversation();return;}ensureConnections();syncAuraLog();wrapIntent=intent;const prior=state.sessionReviews.find(r=>r.logId===activeLogId);if(prior){if(intent==='new'&&prior.messageCount===chatMessages.length){resetConversation();return;}sessionWrap={...prior,messageCount:chatMessages.length};}else sessionWrap={id:crypto.randomUUID(),logId:activeLogId,date:stamp(),helpfulness:null,feeling:null,takeaway:'',memory:true,messageCount:chatMessages.length};sessionWrapStep=0;location.hash='after-chat';if(location.hash==='#after-chat')route();}
function completeSessionWrap(skip=false){ensureConnections();if(!sessionWrap)return;if(!skip){const input=$('#session-takeaway');if(input)sessionWrap.takeaway=input.value;const memory=$('#session-memory');if(memory)sessionWrap.memory=memory.checked;const at=state.sessionReviews.findIndex(r=>r.logId===sessionWrap.logId),review={...sessionWrap,date:stamp()};if(at>=0)state.sessionReviews[at]=review;else state.sessionReviews.push(review);}syncAuraLog();const log=state.chatLogs.find(l=>l.id===sessionWrap.logId);if(log)log.endedAt=stamp();const intent=wrapIntent;sessionWrap=null;sessionWrapStep=0;save();if(intent==='new')resetConversation();else{location.hash='session-done';route();}}
function afterChatPage(){if(!sessionWrap)return `<div class="session-done narrow">${catSymbol()}<h1>Nothing to check in on yet.</h1><a class="primary" href="#chat">Back to chat</a></div>`;const step=sessionWrapStep;if(step===0)return `<div class="after-chat narrow"><p class="session-kicker">BEFORE YOU GO · OPTIONAL</p><h1>Did this conversation help?</h1><div class="wrap-choices">${[['helpful','Yes, it helped'],['mixed','A little'],['not-helpful','Not really']].map(([value,label])=>`<button data-wrap-value="${value}" aria-pressed="${sessionWrap.helpfulness===value}">${label}</button>`).join('')}</div><div class="actions"><button class="primary" data-wrap="next">${sessionWrap.helpfulness?'Continue':'Skip question'} →</button><button class="quiet-button" data-wrap="skip-all">Skip check-in</button></div><a class="return-to-chat" href="#chat">Keep talking instead</a></div>`;
 if(step===1)return `<div class="after-chat narrow"><p class="session-kicker">RIGHT NOW · OPTIONAL</p><h1>How do you feel?</h1><div class="wrap-choices">${[['settled','More settled'],['same','About the same'],['unsettled','More unsettled'],['unsure','Not sure']].map(([value,label])=>`<button data-wrap-value="${value}" aria-pressed="${sessionWrap.feeling===value}">${label}</button>`).join('')}</div><div class="actions"><button class="primary" data-wrap="next">${sessionWrap.feeling?'Continue':'Skip question'} →</button><button class="secondary" data-wrap="back">Back</button><button class="quiet-button" data-wrap="skip-all">Skip check-in</button></div>${sessionWrap.feeling==='unsettled'?'<p class="small">You can pause, try <a href="#ground">grounding</a>, or reach someone you trust. <a href="#support">Human support</a>.</p>':''}</div>`;
 return `<div class="after-chat narrow"><p class="session-kicker">ONE THING TO TAKE WITH YOU</p><h1>Anything worth keeping?</h1><label class="sr-only" for="session-takeaway">Optional takeaway</label><textarea id="session-takeaway" maxlength="1000" placeholder="An insight, a next step, or nothing at all…">${esc(sessionWrap.takeaway)}</textarea><label class="check"><input id="session-memory" type="checkbox" ${sessionWrap.memory!==false?'checked':''}><span>Available to memory ${prefs().reflectionMemory?'':'(currently off)'}</span></label><p class="small">Saved privately using your current storage setting. Shared with Gemini only when check-in memory is enabled.</p><div class="actions"><button class="primary" data-wrap="save">Save & finish</button><button class="secondary" data-wrap="back">Back</button><button class="quiet-button" data-wrap="skip-all">Skip check-in</button></div></div>`;}
function sessionDonePage(){return `<div class="session-done narrow">${catSymbol()}<h1>Take your time.</h1><p>You can come back whenever you want.</p><div class="actions"><button class="primary" data-session="fresh">Start a new conversation</button><a class="text-link" href="#journal">Write a little</a></div><p class="vault-status small">${esc(vaultStatus)}</p></div>`;}
const connectedChatPage=chatPage;chatPage=function(){const p=prefs();return connectedChatPage().replaceAll('data-chat="new"','data-session="new"').replace('New conversation','New chat').replace(/<a class="memory-link"[^>]*>[\s\S]*?<\/a>/,'<a class="memory-link" href="#preferences">'+(p.journalMemory||p.reflectionMemory?'Memory on':'Memory off')+'</a>').replace('Optional journal memory and country are included only if enabled.','Optional journal, weekly and chat check-ins are included only when enabled.').replace('<div class="quiet-chat-actions">','<div class="quiet-chat-actions">'+(chatMessages.some(m=>m.role==='assistant')?'<button data-session="finish" '+(chatBusy?'disabled':'')+'>Finish chat</button>':''));};
const readingBeforeFeedback=logReadingHTML;logReadingHTML=function(){ensureConnections();const html=readingBeforeFeedback(),review=state.sessionReviews.find(r=>r.logId===selectedLog);if(!review)return html;const helpful={helpful:'Helpful',mixed:'Helped a little','not-helpful':'Not helpful'},feeling={settled:'More settled',same:'About the same',unsettled:'More unsettled',unsure:'Not sure'};return html+`<details class="log-feedback"><summary>After-chat check-in</summary><p>${esc(helpful[review.helpfulness]||'Helpfulness skipped')} · ${esc(feeling[review.feeling]||'Feeling skipped')}</p>${review.takeaway?`<p>${esc(review.takeaway)}</p>`:''}<label class="check"><input type="checkbox" data-review-memory="${esc(review.id)}" ${review.memory!==false?'checked':''}><span>Available to check-in memory</span></label><button class="icon-delete" data-review-delete="${esc(review.id)}">Delete check-in</button></details>`;};
const connectionRoute=route;let lastConnectedView='';route=function(){ensureConnections();const hash=location.hash.slice(1);if(hash==='after-chat'||hash==='session-done'){$('#main').innerHTML=hash==='after-chat'?afterChatPage():sessionDonePage();document.body.classList.remove('is-chat');renderCats();}else connectionRoute();if(hash==='preferences')$('#reflection-memory').onchange=e=>{prefs().reflectionMemory=e.target.checked;save();};const key=hash+(hash==='after-chat'?':'+sessionWrapStep:'');if(lastConnectedView!==key&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches){$('#main').animate([{opacity:.3,transform:'translateY(5px)'},{opacity:1,transform:'translateY(0)'}],{duration:260,easing:'ease-out'});lastConnectedView=key;}};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.session==='fresh')resetConversation();if(b.dataset.session==='finish')openSessionWrap('finish');if(b.dataset.session==='new')openSessionWrap('new');if(b.dataset.wrapValue){if(sessionWrapStep===0)sessionWrap.helpfulness=b.dataset.wrapValue;else sessionWrap.feeling=b.dataset.wrapValue;route();}if(b.dataset.wrap==='next'){sessionWrapStep=Math.min(2,sessionWrapStep+1);route();}if(b.dataset.wrap==='back'){if($('#session-takeaway'))sessionWrap.takeaway=$('#session-takeaway').value;sessionWrapStep=Math.max(0,sessionWrapStep-1);route();}if(b.dataset.wrap==='save')completeSessionWrap();if(b.dataset.wrap==='skip-all')completeSessionWrap(true);if(b.dataset.reviewDelete&&confirm('Delete this after-chat check-in? Previously shared AI context and backups are unaffected.')){state.sessionReviews=state.sessionReviews.filter(r=>r.id!==b.dataset.reviewDelete);save();route();}});
document.addEventListener('change',e=>{const id=e.target.dataset?.reviewMemory;if(id){const review=state.sessionReviews.find(r=>r.id===id);if(review){review.memory=e.target.checked;save();}}});
const clearConnectionTransient=window.auraClearTransient;window.auraClearTransient=function(){clearConnectionTransient?.();sessionWrap=null;sessionWrapStep=0;};
const clearConnectionData=window.auraAfterClear;window.auraAfterClear=function(){sessionWrap=null;sessionWrapStep=0;clearConnectionData?.();};
route();
